        if 'T' in row:
            end = (i, row.index('T'))
    return start, end

def bfs(grid, n, m, k, start, end):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[[False] * (k + 1) for _ in range(m)] for _ in range(n)]
    queue = deque([(start[0], start[1], 0, [])])  # (row, col, steps, path)
